const input = $input.first().json;
const qualified = (input.qualified || []).filter(j => (j.matchScore || 0) >= 70);

// Future: route by ATS source (greenhouse, lever, ashby)
// Each source will need its own apply adapter with user consent + CAPTCHA handling

const plan = qualified.map(j => ({
  jobId: j.job.id,
  company: j.job.company,
  title: j.job.title,
  source: j.job.source,
  applyUrl: j.job.applyUrl,
  matchScore: j.matchScore,
  autoApplyStatus: 'pending_implementation',
  note: 'Connect ATS-specific apply nodes here when AUTO_APPLY_ENABLED=true'
}));

return [{ json: { autoApplyPlan: plan, count: plan.length, enabled: true } }];
